  &reftitle.examples;



    Esempio di restore_error_handler


     Determina se unserialize ha causato un errore, poi
     ripristina il gestore degli errori originale.



<?php
function unserialize_handler($errno, $errstr)
{
    echo "Valore serializzato non valido.\n";
}

$serialized = 'foo';
set_error_handler('unserialize_handler');
$original = unserialize($serialized);
restore_error_handler();
?>


    &example.outputs;


Valore serializzato non valido.
